SELECT
ar.ori_user_id,
ar.ori_share_code,
ar.ori_account,
ar.p1_id,
b.register_time as reg_time,

(SELECT count(1) from app_agent_relation where p1_id = ar.ori_user_id ) as line_qty
FROM app_agent_relation ar
LEFT JOIN app_user b on b.id = ar.ori_user_id


        AND ar.top_user_id = #{topUserId}


        AND ar.p1_id = #{req.proxyId}


        AND ar.p1_account = #{req.proxyUserName}


        AND ar.p1_code = #{req.proxyShareCode}


        AND ar.ori_share_code = #{req.oriShareCode}


        AND ar.ori_account = #{req.userName}

